export function createPackManager({load,fa,toast}){
 const $=id=>document.getElementById(id);let catalog={packs:[]},status={packs:[],busy:false};
 const parse=value=>typeof value==='string'?JSON.parse(value):value;
 async function refresh(){try{catalog=await load('full-books/packs.json');}catch{return;}if(window.MansourBooks)status=parse(await Promise.resolve(window.MansourBooks.getInstalledPacks()));render();return status;}
 function render(){const installed=new Set(status.packs.filter(p=>p.installed).map(p=>p.id));$('packs-summary').textContent=`${fa(installed.size)} بسته از ${fa(catalog.packs.length)} بسته وارد شده است.`;$('pack-list').replaceChildren();for(const pack of catalog.packs){const card=document.createElement('article');card.className='source-card';const title=document.createElement('h3');title.textContent=pack.title||pack.id;const info=document.createElement('p');info.textContent=`${fa(Math.round(pack.bytes/1048576))} مگابایت · ${fa(pack.books?.length||0)} مجموعهٔ کتاب`;const state=document.createElement('strong');state.textContent=installed.has(pack.id)?'✓ نصب‌شده و آمادهٔ مطالعه':'نیازمند ورود فایل بسته';const file=document.createElement('p');file.textContent=pack.file;file.dir='ltr';card.append(title,info,state,file);$('pack-list').append(card);}$('import-pack').disabled=status.busy||!window.MansourBooks;}
 $('import-pack').onclick=async()=>{try{if(!window.MansourBooks)return toast('ورود بسته در برنامهٔ نصب‌شدهٔ منصور در دسترس است.');$('import-pack').disabled=true;await Promise.resolve(window.MansourBooks.importBookPack());await refresh();}catch(e){toast(e.message);await refresh();}};
 $('refresh-packs').onclick=()=>refresh().catch(e=>toast(e.message));
 window.addEventListener('mansour-pack-progress',e=>{const d=e.detail;$('pack-progress').textContent=d.state==='verifying'?'در حال کنترل سلامت فایل بسته…':d.state==='extracting'?`در حال ورود فایل‌ها: ${fa(d.files||0)} از ${fa(d.total||0)}`:d.state==='complete'?'بسته وارد شد؛ کتاب‌ها آمادهٔ مطالعه‌اند.':d.state==='cancelled'?'ورود بسته لغو شد.':d.message||'ورود بسته انجام نشد.';if(['complete','error','cancelled'].includes(d.state))setTimeout(()=>refresh().catch(e=>toast(e.message)),200);});
 return {refresh,hasBook:book=>(book.packs||[]).every(id=>status.packs.some(p=>p.id===id&&p.installed))};
}
